-- Sabi seed data: service groups and services, generated from js/data.js.
-- Run this after schema.sql. It is safe to run again: existing rows are updated.

on conflict (id) do update set name = excluded.name, sort = excluded.sort;

on conflict (id) do update set group_id = excluded.group_id, other_groups = excluded.other_groups, name = excluded.name, speed_kind = excluded.speed_kind, speed_label = excluded.speed_label, is_24h = excluded.is_24h, items = excluded.items, score_labels = excluded.score_labels, note = excluded.note;
